const brief = $json.data ?? $json;
const overdue = Array.isArray(brief.overdue) ? brief.overdue : [];
const upcoming = Array.isArray(brief.upcoming) ? brief.upcoming : [];
const waiting = Array.isArray(brief.waiting) ? brief.waiting : [];
const esc = value => String(value ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const formatDate = value => {
  if (!value) return '';
  return new Intl.DateTimeFormat('ru-RU', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Paris' }).format(new Date(value));
};
const line = task => `• ${esc(task.title)}${task.dueAt ? ` — ${formatDate(task.dueAt)}` : ''}`;
const sections = ['<b>Доброе утро, Сергей!</b>', ''];
if (overdue.length) sections.push(`<b>🔴 Просрочено: ${overdue.length}</b>`, ...overdue.slice(0, 10).map(line), '');
if (upcoming.length) sections.push(`<b>🟡 На ближайшие 24 часа: ${upcoming.length}</b>`, ...upcoming.slice(0, 10).map(line), '');
if (waiting.length) sections.push(`<b>⏳ Ждём ответа или события: ${waiting.length}</b>`, ...waiting.slice(0, 10).map(task => `• ${esc(task.title)}${task.waitingFor ? ` — ждём: ${esc(task.waitingFor)}` : ''}`), '');
if (!overdue.length && !upcoming.length && !waiting.length) sections.push('На сегодня срочных и ожидающих задач нет.');
sections.push(`<i>Всего в выборке: ${Number(brief.total ?? 0)}</i>`);
return [{ json: { text: sections.join('\n').trim() } }];
